#include<bits/stdc++.h>
#define elif else if
using namespace std;
int n,m,ans=INT_MAX;
pair<int,int> start,finish;
unordered_map<char,pair<pair<int,int>,pair<int,int> > > csm;
vector<vector<char>> a;
void dfs(int x,int y,int z){
    if(z>=ans)return;
    if(make_pair(x,y)==finish){
        ans=min(ans,z);
        return;
    }
    if(x>1)if(a[x-1][y]!='#'){
        char l=a[x-1][y];
        a[x-1][y]='#';
        dfs(x-1,y,z+1);
        if(l!='.'){
            if(make_pair(x-1,y)==csm[l].first){
                char k1=a[csm[l].second.first][csm[l].second.second];
                if(k1!='#'){
                    a[csm[l].second.first][csm[l].second.second]='#';
                    dfs(csm[l].second.first,csm[l].second.second,z+2);
                    a[csm[l].second.first][csm[l].second.second]=k1;
                }
            }
            else{
                char k2=a[csm[l].first.first][csm[l].first.second];
                if(k2!='#'){
                    a[csm[l].first.first][csm[l].first.second]='#';
                    dfs(csm[l].first.first,csm[l].first.second,z+2);
                    a[csm[l].first.first][csm[l].first.second]=k2;
                }
            }
        }
        a[x-1][y]=l;
    }
    if(x<n)if(a[x+1][y]!='#'){
        char l=a[x+1][y];
        a[x+1][y]='#';
        dfs(x+1,y,z+1);
        if(l!='.'){
            if(make_pair(x+1,y)==csm[l].first){
                char k1=a[csm[l].second.first][csm[l].second.second];
                if(k1!='#'){
                    a[csm[l].second.first][csm[l].second.second]='#';
                    dfs(csm[l].second.first,csm[l].second.second,z+2);
                    a[csm[l].second.first][csm[l].second.second]=k1;
                }
            }
            else{
                char k2=a[csm[l].first.first][csm[l].first.second];
                if(k2!='#'){
                    a[csm[l].first.first][csm[l].first.second]='#';
                    dfs(csm[l].first.first,csm[l].first.second,z+2);
                    a[csm[l].first.first][csm[l].first.second]=k2;
                }
            }
        }
        a[x+1][y]=l;
    }
    if(y>1)if(a[x][y-1]!='#'){
        char l=a[x][y-1];
        a[x][y-1]='#';
        dfs(x,y-1,z+1);
        if(l!='.'){
            if(make_pair(x,y-1)==csm[l].first){
                char k1=a[csm[l].second.first][csm[l].second.second];
                if(k1!='#'){
                    a[csm[l].second.first][csm[l].second.second]='#';
                    dfs(csm[l].second.first,csm[l].second.second,z+2);
                    a[csm[l].second.first][csm[l].second.second]=k1;
                }
            }
            else{
                char k2=a[csm[l].first.first][csm[l].first.second];
                if(k2!='#'){
                    a[csm[l].first.first][csm[l].first.second]='#';
                    dfs(csm[l].first.first,csm[l].first.second,z+2);
                    a[csm[l].first.first][csm[l].first.second]=k2;
                }
            }
        }
        a[x][y-1]=l;
    }
    if(y<m)if(a[x][y+1]!='#'){
        char l=a[x][y+1];
        a[x][y+1]='#';
        dfs(x,y+1,z+1);
        if(l!='.'){
            if(make_pair(x,y+1)==csm[l].first){
                char k1=a[csm[l].second.first][csm[l].second.second];
                if(k1!='#'){
                    a[csm[l].second.first][csm[l].second.second]='#';
                    dfs(csm[l].second.first,csm[l].second.second,z+2);
                    a[csm[l].second.first][csm[l].second.second]=k1;
                }
            }
            else{
                char k2=a[csm[l].first.first][csm[l].first.second];
                if(k2!='#'){
                    a[csm[l].first.first][csm[l].first.second]='#';
                    dfs(csm[l].first.first,csm[l].first.second,z+2);
                    a[csm[l].first.first][csm[l].first.second]=k2;
                }
            }
        }
        a[x][y+1]=l;
    }
}
signed main(){
    ios::sync_with_stdio(0);
    cin.tie(0);cout.tie(0);
    cin>>n>>m;
    a.resize(n+2,vector<char>(m+2));
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            char c;
            cin>>c;
            if(c=='S'){
                c='.';
                start={i,j};
            }
            elif(c=='T'){
                c='.';
                finish={i,j};
            }
            elif(c!='.'&&c!='#'){
                if(csm[c].first.first==0)
                    csm[c].first={i,j};
                else
                    csm[c].second={i,j};
            }
            a[i][j]=c;
        }
    }
    a[start.first][start.second]='#';
    dfs(start.first,start.second,0);
    if(ans==INT_MAX)
        cout<<-1;
    else
        cout<<ans;
    return 0;
}
